import math
import itertools

def closed_loop_poles(gain, tau):
    """Unity feedback of G(s)=1/((s+1)(tau*s+1)), tau>0."""
    real = -(tau + 1) / (2 * tau)
    discriminant = (tau + 1) ** 2 - 4 * tau * (1 + gain)
    if discriminant >= 0:
        offset = math.sqrt(discriminant) / (2 * tau)
        return [real - offset, real + offset], [0.0, 0.0]
    offset = math.sqrt(-discriminant) / (2 * tau)
    return [real, real], [-offset, offset]

def solve(gain, tau):
    return closed_loop_poles(gain, tau)

p10-frequency-delay:
import math
import itertools

def frequency_point(gain, tau, omega, delay):
    """Magnitude and principal phase in degrees of K exp(-sd)/((s+1)(tau*s+1))."""
    value = gain * complex(math.cos(-omega * delay), math.sin(-omega * delay))
    value /= (1 + 1j * omega) * (1 + 1j * tau * omega)
    return abs(value), math.degrees(math.atan2(value.imag, value.real))

def solve(gain, tau, omega, delay):
    return frequency_point(gain, tau, omega, delay)

p10-controllability-two:
import math
import itertools

def controllability_2d(A, B):
    AB = [A[i][0] * B[0] + A[i][1] * B[1] for i in range(2)]
    matrix = [[B[0], AB[0]], [B[1], AB[1]]]
    determinant = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    return matrix, determinant

def solve(A, B):
    return controllability_2d(A, B)

