import math
import itertools

def canonical_feedback(pole1, pole2):
    """A=[[0,1],[0,0]], B=[0,1], u=-Kx."""
    return [pole1 * pole2, -(pole1 + pole2)]

def solve(pole1, pole2):
    return canonical_feedback(pole1, pole2)

