def observability_2d(A, C):
    CA = [C[0] * A[0][j] + C[1] * A[1][j] for j in range(2)]
    matrix = [[C[0], C[1]], CA]
    determinant = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    return matrix, determinant

def solve(A, C):
    return observability_2d(A, C)

p10-bellman-one:
import math
import itertools

def scalar_bellman(a, b, q, r, terminal, state):
    denominator = r + b * b * terminal
    gain = b * terminal * a / denominator
    value_weight = q + a * a * terminal - (a * b * terminal) ** 2 / denominator
    return -gain * state, value_weight * state * state, value_weight

def solve(a, b, q, r, terminal, state):
    return scalar_bellman(a, b, q, r, terminal, state)

p10-discrete-mpc:
import math
import itertools

def discrete_mpc(state, a, b, target, q, r, terminal, actions, horizon, lower, upper):
    """Exact enumeration of a small *discrete-action* MPC, not continuous MPC."""
    best = None
    for sequence in itertools.product(actions, repeat=horizon):
        x = state
        cost = 0.0
        path = [x]
        for u in sequence:
            cost += q * (x - target) ** 2 + r * u * u
            x = a * x + b * u
            path.append(x)
            if not lower <= x <= upper:
                break
        else:
            cost += terminal * (x - target) ** 2
            candidate = (cost, sequence, path)
            if best is None or candidate[:2] < best[:2]:
                best = candidate
    if best is None:
        return 'infeasible', None, None, []
    cost, sequence, path = best
    return 'optimal', sequence[0], cost, path

def solve(state, a, b, target, q, r, terminal, actions, horizon, lower, upper):
    return discrete_mpc(state, a, b, target, q, r, terminal, actions, horizon, lower, upper)

p10-scenario-metrics:
import math
import itertools

def paired_metrics(targets, trajectories, applied, limit, failed):
    """One scenario; failed still counts in the denominator outside this helper."""
    if failed:
        return None, None, None, True
    error = sum((x - goal) ** 2 for x, goal in zip(trajectories, targets)) / len(targets)
    effort = sum(u * u for u in applied) / len(applied) if applied else 0.0
    violation = max([max(0.0, abs(u) - limit) for u in applied] or [0.0])
    return error, effort, violation, False

def solve(targets, trajectories, applied, limit, failed):
    return paired_metrics(targets, trajectories, applied, limit, failed)

p10-paired-differences:
import math
import itertools

def paired_difference(method_a, method_b):
    """Paired scenario differences; failures are returned, not silently dropped."""
    valid = [(a, b) for a, b in zip(method_a, method_b) if a is not None and b is not None]
    diffs = [a - b for a, b in valid]
    mean = sum(diffs) / len(diffs) if diffs else None
    failed = len(method_a) - len(valid)
    return mean, failed, len(valid)

def solve(method_a, method_b):
    return paired_difference(method_a, method_b)

